import type { GetSchemaReturn } from "../configuration/getSchemas";

import { operationDataSchema } from "../configuration/rest/generateOpenAPI";

export const OPERATION_TYPES_HEADER =
  "// Generated by `graphoria codegen` from graphoria.ts and the database. Do not edit.";

export const EMPTY_OPERATION_TYPES = `${OPERATION_TYPES_HEADER}\nexport {};\n`;

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null && !Array.isArray(value);

/**
 * The TypeScript type of what an operation's data schema describes. It emits
 * objects, arrays, string, number and boolean, and `{}` for what no JSON type
 * describes. `nullable` is read only on a list's scalar and list items: elsewhere it
 * repeats `required`, and on a list of objects it sits on `items`.
 */
export const typeOfSchema = (schema: unknown): string => {
  if (!isRecord(schema)) return "unknown";

  switch (schema["type"]) {
    case "string":
    case "number":
    case "boolean":
      return schema["type"];
    case "array": {
      const items = schema["items"];
      const item = typeOfSchema(items);
      const nullableItem =
        isRecord(items) && items["type"] !== "object" && items["nullable"] === true;
      return nullableItem ? `(${item} | null)[]` : `${item}[]`;
    }
    case "object": {
      const properties = isRecord(schema["properties"]) ? schema["properties"] : {};
      const required = new Set(Array.isArray(schema["required"]) ? schema["required"] : []);
      const members = Object.entries(properties).map(([key, value]) => {
        const type = typeOfSchema(value);
        if (required.has(key)) return `${key}: ${type};`;
        // Absent under @skip, @include or @when, or null.
        return type === "unknown" ? `${key}?: unknown;` : `${key}?: ${type} | null;`;
      });
      return members.length
        ? `{ ${members.join(" ")} }`.replace(/; }$/, " }")
        : "Record<string, never>";
    }
    default:
      return "unknown";
  }
};

export const renderOperationTypes = (outputs: Record<string, unknown>): string => {
  const entries = Object.entries(outputs);
  // An empty interface fails a consumer's no-empty-object-type lint.
  if (entries.length === 0) return EMPTY_OPERATION_TYPES;

  return [
    OPERATION_TYPES_HEADER,
    "declare global {",
    "  interface GraphoriaGeneratedOperationOutputs {",
    ...entries.map(
      ([name, schema]) =>
        `    ${IDENTIFIER.test(name) ? name : JSON.stringify(name)}: ${typeOfSchema(schema)};`,
    ),
    "  }",
    "}",
    "export {};",
    "",
  ].join("\n");
};

/**
 * The operations a tRPC client cannot type from `graphoria.ts` alone: a `query`
 * with no `output` and no `afterRequest` (which reshapes the answer), and that
 * validates (a query that does not answers no data). A gql.tada document is
 * printed to a string too, so it gets an entry, which its own type keeps unread.
 */
export const operationOutputs = (role: GetSchemaReturn) => {
  const outputs: Record<string, Record<string, unknown>> = {};
  for (const [name, operation] of Object.entries(role.handlers.rest.operationsEnhanced)) {
    if (
      operation.authOperation ||
      !operation.queryStructure ||
      operation.hasError ||
      operation.output ||
      operation.hooks?.afterRequest
    ) {
      continue;
    }
    outputs[name] = operationDataSchema(operation, role);
  }
  return outputs;
};
